 static QString tr8(const char*s){return QString::fromUtf8(s);}
 static QJsonObject json(QString path){QFile f(path);if(!f.open(QIODevice::ReadOnly)||f.size()>1000000)throw std::runtime_error("Cannot read evaluation report");QJsonParseError e;auto d=QJsonDocument::fromJson(f.readAll(),&e);if(e.error!=QJsonParseError::NoError||!d.isObject())throw std::runtime_error("Invalid evaluation report");return d.object();}
 void setActive(bool value){if(active==value)return;active=value;for(auto*w:QList<QWidget*>{structure,kind,reference,description,tolerance,start,browse})w->setEnabled(!value);if(changed)changed(value);}
 void lines(QByteArray data){pending+=data;while(pending.contains('\n')){int end=pending.indexOf('\n');auto row=pending.left(end);pending.remove(0,end+1);auto d=QJsonDocument::fromJson(row);if(!d.isObject())continue;auto o=d.object();if(o["event"]=="progress")status->setText(tr8("正在计算完整体素与拓扑指标，界面可继续操作"));if(o["event"]=="error")stderrText=o["text"].toString();if(o["event"]=="mask_evaluation_completed"){reportPath=o["metrics"].toString();contextPath=o["context"].toString();}}}
 void finish(int code,QProcess::ExitStatus exit){lines(worker.readAllStandardOutput());stderrText+=QString::fromUtf8(worker.readAllStandardError());setActive(false);if(code||exit!=QProcess::NormalExit||reportPath.isEmpty()){status->setText(tr8("评估未完成：")+stderrText.right(1500));return;}try{auto r=json(reportPath),c=json(contextPath);if(r["schema"]!="kv260.mask_evaluation.v1"||r["status"]!="completed"||c["schema"]!="kv260.mask_evaluation.context.v1"||c["case_ct"].toString()!=QFileInfo(ct).canonicalFilePath()||c["structure"].toString()!=structure->currentData().toString())throw std::runtime_error("Evaluation context does not match this case");auto metrics=r["metrics"].toObject();int row=0;table->setRowCount(0);QMap<QString,QString> labels={{"dice",tr8("Dice")},{"iou",tr8("IoU")},{"precision",tr8("精度")},{"recall_sensitivity",tr8("召回率")},{"centerline_precision",tr8("中心线精度")},{"tree_length_detected_recall",tr8("树长检出召回")},{"centerline_dice",tr8("中心线 Dice")},{"tolerance_mm",tr8("距离容差 mm")},{"pred_connected_components",tr8("预测连通域数")},{"gt_connected_components",tr8("参考连通域数")},{"pred_endpoints",tr8("预测端点数")},{"gt_endpoints",tr8("参考端点数")},{"pred_junction_clusters",tr8("预测分岔簇数")},{"gt_junction_clusters",tr8("参考分岔簇数")},{"pred_centerline_length_mm",tr8("预测中心线长 mm")},{"gt_centerline_length_mm",tr8("参考中心线长 mm")},{"pred_volume_ml",tr8("预测体积 mL")},{"gt_volume_ml",tr8("参考体积 mL")}};for(auto group:{"voxel_metrics","topology_metrics","volume_metrics"}){auto values=metrics[group].toObject();if(values.isEmpty())throw std::runtime_error("Missing original metric group");for(auto it=values.begin();it!=values.end();++it){table->insertRow(row);table->setItem(row,0,new QTableWidgetItem(labels.value(it.key(),it.key())));table->setItem(row++,1,new QTableWidgetItem(QString::number(it.value().toDouble(),'g',12)));}}status->setText(QString(tr8("已完成 · %1 秒 · %2\n报告：%3%4")).arg(r["elapsed_seconds"].toDouble(),0,'f',2).arg(kind->currentText()).arg(reportPath).arg(r["prediction_reference_same_content"].toBool()?tr8("\n预测与参考的文件内容相同"):QString()));}catch(const std::exception&e){table->setRowCount(0);status->setText(QString::fromUtf8(e.what()));}}
protected:
